questionvariables.text:
/* Listes de paramètres */
list_V_affichage: [1/2000, 1/1000, 1/500, 1/250, 1/125, 1/60, 1/30, 1/15, 1/8, 1/4, 1/2, 1, 2];
list_D_affichage: [1, 1.4, 2, 2.8, 4, 5.6, 8, 11, 16, 22];
list_D_reelles: [1, sqrt(2), 2, 2*sqrt(2), 4, 4*sqrt(2), 8, 8*sqrt(2), 16, 16*sqrt(2)];

valid: false;
while not valid do (
  /* Tirage initial */
  idx_D1: rand(length(list_D_affichage)) + 1,
  D1_affichage: list_D_affichage[idx_D1],
  D1_reel: list_D_reelles[idx_D1],
  V1: rand(list_V_affichage),
  I1: 400, /* ISO constants */

  /* Nouveau diaphragme cible */
  idx_D2: rand(delete(idx_D1, makelist(i, i, 1, length(list_D_affichage)))),
  D2_affichage: list_D_affichage[idx_D2],
  D2_reel: list_D_reelles[idx_D2],

  /* Calcul de la vitesse théorique : V2 = V1 * (D2_reel / D1_reel)^2 */
  V2_theorique: float(V1 * (D2_reel / D1_reel)^2),

  /* Trouver la vitesse standard la plus proche */
  diffs: map(lambda([x], abs(float(x) - V2_theorique)), list_V_affichage),
  min_diff: lmin(diffs),
  idx_V2: first(sublist(makelist(i, i, 1, length(list_V_affichage)), 
                        lambda([i], abs(float(list_V_affichage[i]) - V2_theorique) = min_diff))),

  V2_standard: list_V_affichage[idx_V2],

  /* Validation : l'écart doit être faible pour que l'exercice reste réaliste */
  if (min_diff / V2_theorique < 0.1) then valid: true
);

/* Variable de réponse pour STACK */
V_cible: V2_standard;

/* Préparation des options pour le bouton radio */
/* On utilise string(x) pour la valeur de retour et l'affichage personnalisé pour le label */
ta1: map(lambda([x], [x, is(x = V_cible), sconcat(x, " s")]), list_V_affichage);

/* Variables pour le feedback général */
diaphragme_ferme: if D2_affichage > D1_affichage then true else false;

n1_exact: (D1_reel/D2_reel)^2;
n2_exact: (D2_reel/D1_reel)^2;
n1: I2/I1;
n2: I1/I2;

n3: I2/I1;
n4: I1/I2;

n7_exact: if V2 > V1 then V2/V1 else V1/V2;
n7: 2^round(log(n7_exact)/log(2));
